import {
  TuituiBotClient,
  type TuituiEventMessage,
  type TuituiEventTeamsPost,
} from "@qihoo/tuitui-bot-sdk";
import { loadSampleConfig } from "./config.js";

function timestamp(): string {
  return new Date().toISOString();
}

const config = loadSampleConfig();
const client = new TuituiBotClient(config.appId, config.appSecret);

const subscription = client.event.subscribe({
  onConnected() {
    console.log(`[${timestamp()}] tuitui bot(${config.appId}) 已连接websocket，正在监听事件`);
  },
  onEvent(body) {
    const eventName = body.event;

    console.log(`[${timestamp()}] ${body.bot_name} 收到事件:${eventName}`);
    console.log(JSON.stringify(body, null, 2));

    switch (eventName) {
      case client.event.SINGLE_CHAT: {
        const message = body as TuituiEventMessage;
        const text = client.event.renderMessageBody(message.data);
        console.log(`[${timestamp()}] 单聊解析文本:\n${text}`);
        break;
      }
      case client.event.GROUP_CHAT: {
        const message = body as TuituiEventMessage;
        const text = client.event.renderMessageBody(message.data);
        console.log(`[${timestamp()}] 群聊解析文本:\n${text}`);
        console.log(`[${timestamp()}] 群聊是否@自己:${message.data.at_me ?? false}`);
        break;
      }
      case client.event.TEAMS_POST_CREATE: {
        const post = body as TuituiEventTeamsPost;
        console.log(`[${timestamp()}] 团队帖子解析文本:\n${post.data.content}`);
        console.log(`[${timestamp()}] 团队帖子是否@自己:${post.data.at_me}`);
        break;
      }
    }
  },
  onError(error) {
    console.error(`[${timestamp()}] tuitui websocket`, error);
  },
});

process.once("SIGINT", () => {
  console.log(`\n[${timestamp()}] 停止监听`);
  subscription.unsubscribe();
});
